    forward 按输入形状解析。其他 str 抛 ValueError，其他类型（含 bool）
    抛 TypeError。
    """
    if isinstance(value, str):
        if value not in ("same", "valid"):
            raise ValueError(
                "padding 字符串必须是 'same' 或 'valid'，得到 %r" % value
            )
        return value
    if isinstance(value, bool) or not isinstance(value, (int, tuple)):
